import fs from 'fs';
const categories = {
  'Skrypt — Wywody Wody Werki': [
    { oldQ: 'Najczęstsza postać ostrej niewydolności nerek:', q: 'Jaka jest najczęstsza postać ostrej niewydolności nerek?', o: ['postać przednerkowa (50-70% przypadków, wynikająca z hipoperfuzji nerek)', 'postać nerkowa (miąższowa)', 'postać zanerkowa (pozanerkowa, z przeszkody w odpływie moczu)', 'postać przewlekła nakładająca się na ostrą', 'postać polekowa jako jedyna istotna przyczyna'], a: 0, rationale: "Poprawnie: ostra niewydolność nerek przednerkowa, wynikająca z hipoperfuzji nerek (np. odwodnienie, hipotensja, niewydolność serca), stanowi 50-70% przypadków i jest najczęstszą postacią. Postać nerkowa (miąższowa, np. ostra martwica cewek) jest rzadsza niż przednerkowa, choć istotna klinicznie. Postać zanerkowa (przeszkoda podpęcherzowa/moczowodowa) jest najrzadszą z trzech głównych kategorii ostrej niewydolności nerek. Ostra niewydolność nerek z definicji jest stanem ostrym, odrębnym od przewlekłej choroby nerek — nie jest zdefiniowana jako nałożenie się obu procesów. Przyczyny polekowe mogą powodować różne postacie (przednerkową przez odwodnienie lub nerkową przez nefrotoksyczność), ale nie są jedyną istotną przyczyną tej jednostki." },
    { oldQ: 'Które związki hamują aktywację płytek krwi i ich adhezję do śródbłonka:', q: 'Które związki fizjologicznie hamują aktywację płytek krwi i ich adhezję do śródbłonka?', o: ['tlenek azotu (NO) i prostacyklina (PGI2)', 'tromboksan A2 i trombina', 'kolagen i czynnik von Willebranda', 'ADP i serotonina uwalniane z płytek', 'endotelina-1 i angiotensyna II'], a: 0, rationale: "Poprawnie: NO i prostacyklina, wydzielane przez prawidłowy śródbłonek, hamują aktywację i agregację płytek krwi, utrzymując płynność krwi w nieuszkodzonych naczyniach. Tromboksan A2 i trombina działają PRZECIWNIE — silnie aktywują i pobudzają agregację płytek krwi. Kolagen i czynnik von Willebranda promują adhezję płytek do uszkodzonego śródbłonka, inicjując proces krzepnięcia, a nie go hamując. ADP i serotonina uwalniane z aktywowanych płytek nasilają dalszą agregację płytek (dodatnie sprzężenie zwrotne), nie hamują jej. Endotelina-1 i angiotensyna II są substancjami obkurczającymi naczynia, niezwiązanymi z hamowaniem aktywacji płytek — nie pełnią tej ochronnej roli co NO i prostacyklina." },
    { oldQ: 'Najczęstsza przyczyna zawału mięśnia sercowego:', q: 'Jaka jest najczęstsza przyczyna zawału mięśnia sercowego?', o: ['pęknięcie blaszki miażdżycowej i powstały na jej tle zakrzep', 'skurcz naczynia wieńcowego bez zmian miażdżycowych', 'zator tętnicy wieńcowej pochodzenia sercowego', 'zapalenie naczyń wieńcowych (vasculitis)', 'rozwarstwienie tętnicy wieńcowej niezwiązane z miażdżycą'], a: 0, rationale: "Poprawnie: najczęstszą przyczyną zawału mięśnia sercowego jest pęknięcie (lub nadżerka) niestabilnej blaszki miażdżycowej z następowym powstaniem zakrzepu zamykającego światło tętnicy wieńcowej. Izolowany skurcz naczynia bez zmian miażdżycowych (angina Prinzmetala) jest znacznie rzadszą przyczyną zawału niż pęknięcie blaszki. Zator pochodzenia sercowego (np. z lewego przedsionka w migotaniu przedsionków) jest rzadszą przyczyną zawału w porównaniu z miażdżycowym mechanizmem zakrzepowym. Zapalenie naczyń wieńcowych jest rzadką, nietypową przyczyną zawału, znacznie mniej powszechną niż miażdżyca. Samoistne rozwarstwienie tętnicy wieńcowej jest rzadszą, choć ważną klinicznie przyczyną zawału, zwłaszcza u młodszych kobiet, ale nie jest najczęstszym mechanizmem." },
    { oldQ: 'Efekt odruchu Bezolda-Jarischa (składowa sercowa vs naczyniowa):', q: 'Jaki jest efekt odruchu Bezolda-Jarischa i która jego składowa jest silniejsza?', o: ['zwolnienie rytmu serca i rozszerzenie naczyń krwionośnych, przy czym składowa sercowa (bradykardia) jest silniejsza', 'przyspieszenie rytmu serca i zwężenie naczyń krwionośnych', 'zwolnienie rytmu serca i rozszerzenie naczyń, przy czym składowa naczyniowa jest silniejsza', 'wyłącznie zwężenie naczyń bez wpływu na rytm serca', 'wyłącznie przyspieszenie rytmu serca bez wpływu na naczynia'], a: 0, rationale: "Poprawnie: odruch Bezolda-Jarischa, wywoływany pobudzeniem receptorów w ścianie lewej komory, wywołuje bradykardię i rozszerzenie naczyń, przy czym składowa sercowa (zwolnienie rytmu) jest silniejsza od naczyniowej. Twierdzenie o przyspieszeniu rytmu i zwężeniu naczyń jest odwróceniem rzeczywistego kierunku działania tego odruchu. Choć obie składowe (bradykardia i wazodylatacja) występują, to składowa sercowa jest dominująca — twierdzenie o przewadze składowej naczyniowej odwraca tę relację. Odruch wpływa jednocześnie na rytm serca i napięcie naczyń, więc ograniczenie wyłącznie do zwężenia naczyń pomija kluczowy, dominujący komponent sercowy. Ograniczenie wyłącznie do przyspieszenia rytmu bez wpływu na naczynia pomija zarówno kierunek działania (bradykardia, nie tachykardia), jak i istotny komponent naczyniowy." },
    { oldQ: 'Jaka jest funkcja komórek urzęsionych w drogach oddechowych:', q: 'Jaka jest funkcja komórek urzęsionych nabłonka dróg oddechowych?', o: ['usuwają śluz wraz z uwięzionymi cząstkami z drzewa oddechowego (transport śluzowo-rzęskowy)', 'wydzielają surfaktant zmniejszający napięcie powierzchniowe pęcherzyków', 'wydzielają kwas solny neutralizujący wdychane patogeny', 'produkują przeciwciała IgA wydzielane do światła dróg oddechowych', 'kurczą oskrzela w odpowiedzi na alergen'], a: 0, rationale: "Poprawnie: komórki urzęsione, poprzez skoordynowany ruch rzęsek, transportują śluz wraz z uwięzionymi cząstkami i drobnoustrojami w kierunku gardła, oczyszczając drogi oddechowe (transport śluzowo-rzęskowy). Surfaktant jest wydzielany przez pneumocyty typu II w pęcherzykach płucnych, odrębne komórki od nabłonka urzęsionego dróg oddechowych. Drogi oddechowe fizjologicznie nie wydzielają kwasu solnego — to funkcja żołądka, niezwiązana z obroną dróg oddechowych. Przeciwciała IgA są produkowane przez plazmocyty błony śluzowej, a nie przez komórki urzęsione, choć obie linie komórkowe współpracują w obronie śluzówkowej. Skurcz oskrzeli w odpowiedzi na alergen jest funkcją mięśni gładkich oskrzeli, regulowanych przez układ nerwowy i mediatory zapalne, nie funkcją komórek urzęsionych." },
    { oldQ: 'Który fragment drzewa oskrzelowego jest pierwszym pozbawionym tkanki chrzęstnej (lek rozszerzający oskrzela zadziała dopiero od tego poziomu):', q: 'Który fragment drzewa oskrzelowego jest pierwszym, w którym brakuje tkanki chrzęstnej (od tego poziomu może zadziałać lek rozszerzający oskrzela)?', o: ['oskrzelik', 'oskrzele główne', 'oskrzele płatowe', 'oskrzele segmentowe', 'tchawica'], a: 0, rationale: "Poprawnie: oskrzeliki są pierwszym odcinkiem drzewa oskrzelowego pozbawionym chrząstki w ścianie, dzięki czemu ich średnica może być regulowana przez skurcz mięśni gładkich (i modyfikowana lekami rozszerzającymi oskrzela). Oskrzela główne posiadają w ścianie tkankę chrzęstną, stabilizującą ich światło niezależnie od napięcia mięśni gładkich. Oskrzela płatowe, podobnie jak główne, zawierają chrząstkę w swojej ścianie, będąc wyższymi piętrami drzewa oskrzelowego niż oskrzeliki. Oskrzela segmentowe wciąż zawierają fragmenty chrząstki w ścianie, będąc powyżej oskrzelików w hierarchii rozgałęzień. Tchawica ma w pełni ukształtowane pierścienie chrzęstne, będąc najwyższym, najbardziej proksymalnym odcinkiem drzewa oddechowego." },
    { oldQ: 'Z czego wynika obecność patologicznego załamka Q po przebytym zawale STEMI:', q: 'Z czego wynika obecność patologicznego załamka Q w EKG po przebytym zawale STEMI?', o: ['z braku aktywności elektrycznej blizny pozawałowej i braku wektora elektrycznego ze ściany przeciwległej', 'z nadmiernej, wzmożonej aktywności elektrycznej blizny pozawałowej', 'z przerostu mięśnia komory w miejscu przebytego zawału', 'z przyspieszonego przewodzenia impulsu przez bliznę pozawałową', 'z zwiększonej perfuzji naczyniowej w obszarze przebytego zawału'], a: 0, rationale: "Poprawnie: martwicza, włóknista blizna pozawałowa jest elektrycznie nieaktywna, przez co brakuje wektora depolaryzacji skierowanego w stronę tej ściany, co elektrokardiograficznie ujawnia się jako patologiczny załamek Q (odzwierciedlający dominujący wektor z przeciwległej, zdrowej ściany). Twierdzenie o wzmożonej aktywności elektrycznej blizny jest sprzeczne z jej naturą — tkanka bliznowata jest martwa elektrycznie, nie nadaktywna. Przerost mięśnia jest odrębnym procesem strukturalnym, niebędącym mechanizmem powstawania załamka Q po zawale. Przewodzenie impulsu przez włóknistą bliznę jest UPOŚLEDZONE, nie przyspieszone — tkanka bliznowata nie przewodzi prawidłowo impulsów elektrycznych. Obszar pozawałowej blizny ma ZMNIEJSZONĄ, a nie zwiększoną perfuzję, co jest zgodne z martwicą tkanki po niedokrwieniu." },
    { oldQ: 'Co sugeruje jednocześnie podwyższone stężenie TSH i T4 w badaniach przesiewowych:', q: 'Co sugeruje jednoczesne podwyższenie stężenia TSH i wolnej T4 w badaniach przesiewowych czynności tarczycy?', o: ['wtórną nadczynność tarczycy (np. gruczolak przysadki wydzielający TSH)', 'pierwotną nadczynność tarczycy (np. chorobę Gravesa-Basedowa)', 'pierwotną niedoczynność tarczycy (np. zapalenie Hashimoto)', 'wtórną niedoczynność tarczycy (uszkodzenie przysadki)', 'stan eutyreozy bez żadnej patologii tarczycowej'], a: 0, rationale: "Poprawnie: jednoczesne podwyższenie TSH i T4 jest nietypowym, ale charakterystycznym obrazem wtórnej (przysadkowej) nadczynności tarczycy, np. w rzadkim gruczolaku przysadki wydzielającym nadmiar TSH, który stymuluje tarczycę do nadprodukcji T4 mimo wysokiego TSH (brak prawidłowego hamowania zwrotnego). Pierwotna nadczynność tarczycy (np. Graves) daje WYSOKIE T4 przy NISKIM (zahamowanym) TSH — odwrotny wzorzec do opisanego. Pierwotna niedoczynność tarczycy daje wysokie TSH przy NISKIM T4 (kompensacyjny wzrost TSH wobec niedoczynnego gruczołu) — sprzeczne z podwyższonym T4 w pytaniu. Wtórna niedoczynność tarczycy (uszkodzenie przysadki) dałaby NISKIE zarówno TSH, jak i T4 — sytuację przeciwną do opisanej. Stan eutyreozy charakteryzuje się prawidłowymi, a nie podwyższonymi wartościami obu hormonów." },
    { oldQ: 'Jeśli objętość wyrzutowa komory wynosi 60 ml, a objętość późnoskurczowa 40 ml, ile wynosi objętość końcoworozkurczowa i frakcja wyrzutowa:', q: 'Jeśli objętość wyrzutowa komory wynosi 60 ml, a objętość końcowoskurczowa 40 ml, ile wynosi objętość końcoworozkurczowa i frakcja wyrzutowa?', o: ['objętość końcoworozkurczowa = 100 ml, frakcja wyrzutowa = 60%', 'objętość końcoworozkurczowa = 20 ml, frakcja wyrzutowa = 300%', 'objętość końcoworozkurczowa = 100 ml, frakcja wyrzutowa = 40%', 'objętość końcoworozkurczowa = 60 ml, frakcja wyrzutowa = 100%', 'objętość końcoworozkurczowa = 40 ml, frakcja wyrzutowa = 150%'], a: 0, rationale: "Poprawnie: objętość końcoworozkurczowa = objętość wyrzutowa + objętość końcowoskurczowa = 60 + 40 = 100 ml; frakcja wyrzutowa = objętość wyrzutowa / objętość końcoworozkurczowa × 100% = 60/100 × 100% = 60%. Odejmowanie zamiast dodawania (60-40=20 ml) błędnie zmniejsza objętość końcoworozkurczową, dając fizjologicznie niemożliwą frakcję wyrzutową powyżej 100%. Podzielenie objętości wyrzutowej przez błędnie obliczoną objętość końcoworozkurczową (100 ml) przez objętość końcowoskurczową zamiast przez EDV daje błędny wynik 40%, niezgodny z definicją EF. Przyjęcie EDV równej samej objętości wyrzutowej (60 ml) jest matematycznie niepoprawne i dałoby fizjologicznie niemożliwą EF=100%. Błędne przyjęcie EDV jako samej objętości końcowoskurczowej (40 ml) prowadzi do niemożliwej fizjologicznie EF powyżej 100%." },
    { oldQ: 'Do funkcji endokrynnej łożyska nie należy wydzielanie jakiego hormonu:', q: 'Wydzielanie którego hormonu NIE należy do funkcji endokrynnej łożyska?', o: ['hormonu luteinizującego (LH)', 'gonadotropiny kosmówkowej (hCG)', 'progesteronu', 'estrogenów', 'ludzkiego laktogenu łożyskowego (hPL)'], a: 0, rationale: "Poprawnie: LH jest wydzielany przez przysadkę mózgową, nie przez łożysko, które zamiast tego produkuje analogiczny funkcjonalnie hCG. Gonadotropina kosmówkowa (hCG) jest jednym z kluczowych, dobrze znanych hormonów wydzielanych przez łożysko (trofoblast) od wczesnej ciąży. Progesteron jest istotnym hormonem steroidowym produkowanym przez łożysko, zwłaszcza od 4. miesiąca ciąży. Estrogeny są, obok progesteronu, głównymi hormonami steroidowymi wydzielanymi przez łożysko w ciąży. Ludzki laktogen łożyskowy (hPL) jest hormonem białkowym charakterystycznym właśnie dla łożyska, wpływającym na metabolizm matki." },
    { oldQ: 'Który pomiar temperatury ciała jest najbardziej zbliżony do temperatury centralnej:', q: 'Który z powierzchownych pomiarów temperatury ciała jest najbardziej zbliżony do temperatury centralnej (spośród pomiaru w uchu, dole pachowym, na czole i w jamie ustnej)?', o: ['pomiar w jamie ustnej', 'pomiar w dole pachowym', 'pomiar na czole (termometrem powierzchniowym)', 'pomiar w uchu bez kontaktu z błoną bębenkową', 'wszystkie wymienione pomiary są jednakowo dokładne'], a: 0, rationale: "Poprawnie: spośród wymienionych metod pomiar w jamie ustnej jest najbardziej zbliżony do rzeczywistej temperatury centralnej, choć wciąż mniej dokładny niż pomiar w przełyku. Pomiar w dole pachowym jest jedną z mniej dokładnych metod, silnie zależną od ucieplenia skóry i warunków otoczenia. Pomiar na czole odzwierciedla temperaturę powierzchowną skóry, silnie zależną od warunków zewnętrznych, będąc jedną z mniej wiarygodnych metod. Pomiar w uchu bez odpowiedniego kontaktu z błoną bębenkową traci dokładność, będącą kluczową zaletą tej metody przy prawidłowym wykonaniu. Dokładność wymienionych metod wyraźnie się różni — nie są one jednakowo wiarygodne, co jest właśnie istotą tego pytania." },
    { oldQ: 'Jak nazywamy pobudzenie dodatkowe serca, które nie wpływa na podstawowy rytm:', q: 'Jak nazywamy pobudzenie dodatkowe serca, które nie zaburza (nie resetuje) podstawowego rytmu zatokowego?', o: ['pobudzeniem wtrąconym (interpolowanym)', 'pobudzeniem z pauzą wyrównawczą', 'pobudzeniem ucieczkowym', 'blokiem zatokowo-przedsionkowym', 'migotaniem komór'], a: 0, rationale: "Poprawnie: pobudzenie wtrącone (interpolowane) wciska się pomiędzy dwa prawidłowe pobudzenia zatokowe bez zaburzania podstawowego rytmu i bez wywoływania pauzy wyrównawczej. Pobudzenie z pauzą wyrównawczą (typowe dla klasycznych skurczów dodatkowych komorowych) właśnie ZABURZA rytm podstawowy, powodując przerwę przed kolejnym prawidłowym pobudzeniem — przeciwieństwo pobudzenia wtrąconego. Pobudzenie ucieczkowe powstaje w odpowiedzi na brak impulsu z węzła nadrzędnego (np. przy zatrzymaniu zatokowym), stanowiąc mechanizm zabezpieczający, a nie pobudzenie dodatkowe niezaburzające rytmu. Blok zatokowo-przedsionkowy to zaburzenie przewodzenia, a nie rodzaj dodatkowego pobudzenia. Migotanie komór jest śmiertelnie groźną arytmią całkowicie dezorganizującą rytm serca, zupełnie odmiennym zjawiskiem od pojedynczego pobudzenia wtrąconego." },
    { oldQ: 'Skutkiem czego jest poliuria po nadmiernym spożyciu etanolu:', q: 'Skutkiem czego jest poliuria obserwowana po nadmiernym spożyciu etanolu?', o: ['zahamowania wydzielania wazopresyny (ADH) przez etanol', 'nasilonego wydzielania wazopresyny przez etanol', 'nasilonego wydzielania aldosteronu przez etanol', 'bezpośredniego toksycznego uszkodzenia kanalików nerkowych przez etanol', 'zahamowania filtracji kłębuszkowej przez etanol'], a: 0, rationale: "Poprawnie: etanol hamuje wydzielanie wazopresyny przez podwzgórze/przysadkę, co zmniejsza reabsorpcję wody w cewkach zbiorczych i prowadzi do zwiększonego wydalania rozcieńczonego moczu (poliurii), przyczyniając się do odwodnienia po spożyciu alkoholu. Twierdzenie o nasilonym wydzielaniu wazopresyny jest odwróceniem rzeczywistego, dobrze udokumentowanego mechanizmu działania etanolu. Etanol nie nasila wydzielania aldosteronu jako głównego mechanizmu poliurii — kluczowym efektem jest zahamowanie ADH, niezwiązane bezpośrednio z aldosteronem. Poliuria po alkoholu wynika z mechanizmu hormonalnego (zahamowanie ADH), a nie z bezpośredniego toksycznego uszkodzenia kanalików nerkowych. Filtracja kłębuszkowa nie jest głównie zahamowana w tym mechanizmie — zwiększone wydalanie moczu wynika ze zmniejszonej reabsorpcji wody, nie ze wzrostu ani spadku filtracji." },
    { oldQ: 'Co powoduje starczowzroczność:', q: 'Co jest przyczyną starczowzroczności (prezbiopii)?', o: ['spadek elastyczności soczewki oka wraz z wiekiem', 'wzrost elastyczności soczewki oka', 'zmętnienie soczewki oka (zaćma)', 'wzrost ciśnienia śródgałkowego', 'zwyrodnienie plamki żółtej związane z wiekiem'], a: 0, rationale: "Poprawnie: starczowzroczność wynika z postępującej z wiekiem utraty elastyczności soczewki, upośledzającej zdolność akomodacji (ogniskowania na bliskich przedmiotach). Wzrost elastyczności soczewki jest odwróceniem rzeczywistego procesu starzenia — z wiekiem soczewka staje się sztywniejsza, nie bardziej elastyczna. Zmętnienie soczewki (zaćma) jest odrębną jednostką chorobową, różną od starczowzroczności, choć również związaną z wiekiem. Wzrost ciśnienia śródgałkowego jest mechanizmem jaskry, zupełnie odrębnej choroby oka niezwiązanej z akomodacją. Zwyrodnienie plamki żółtej (AMD) jest odrębną, związaną z wiekiem chorobą siatkówki, niezwiązaną z mechanizmem akomodacji soczewki." },
    { oldQ: 'Uszkodzenie górnego (centralnego) neuronu ruchowego prowadzi do:', q: 'Uszkodzenie górnego (centralnego) neuronu ruchowego prowadzi typowo do jakiego rodzaju niedowładu?', o: ['niedowładu spastycznego', 'niedowładu wiotkiego', 'wyłącznie zaburzeń czucia bez deficytu ruchowego', 'zaniku mięśni jako dominującego, pierwszoplanowego objawu', 'drżenia spoczynkowego typowego dla choroby Parkinsona'], a: 0, rationale: "Poprawnie: uszkodzenie górnego neuronu ruchowego (drogi korowo-rdzeniowej) daje niedowład spastyczny — wzmożone napięcie mięśniowe, wygórowane odruchy, obecny objaw Babińskiego. Niedowład wiotki jest typowy dla uszkodzenia DOLNEGO neuronu ruchowego (rdzeń, korzenie, nerwy obwodowe), nie górnego. Uszkodzenie górnego neuronu ruchowego daje przede wszystkim deficyt RUCHOWY, choć może współistnieć z zaburzeniami czucia przy uszkodzeniach sąsiednich struktur — nie jest to jednak izolowany deficyt czuciowy. Znaczący zanik mięśni jest bardziej typowy dla uszkodzenia DOLNEGO neuronu ruchowego (odnerwienie), nie dla uszkodzenia górnego, gdzie dominuje spastyczność bez wczesnego, wyraźnego zaniku. Drżenie spoczynkowe jest typowe dla uszkodzenia układu pozapiramidowego (np. w chorobie Parkinsona), odrębnego od drogi korowo-rdzeniowej." },
    { oldQ: 'Na co centralne chemoreceptory w pniu mózgu reagują zwiększeniem częstości oddechów:', q: 'Na co reagują centralne chemoreceptory w pniu mózgu zwiększeniem częstości oddechów?', o: ['na wzrost stężenia CO2 i jonów H+ w ich otoczeniu (płynie mózgowo-rdzeniowym)', 'na spadek pO2 we krwi tętniczej, niezależnie od poziomu CO2', 'na wzrost ciśnienia tętniczego krwi', 'na spadek stężenia glukozy w płynie mózgowo-rdzeniowym', 'na wzrost temperatury krwi tętniczej'], a: 0, rationale: "Poprawnie: centralne chemoreceptory reagują przede wszystkim na wzrost stężenia CO2 (poprzez wynikający z tego spadek pH/wzrost H+) w płynie mózgowo-rdzeniowym, będąc głównym mechanizmem regulacji wentylacji w warunkach fizjologicznych. Bezpośrednia reakcja na spadek pO2 jest domeną chemoreceptorów OBWODOWYCH, nie ośrodkowych, które są stosunkowo mało wrażliwe na hipoksję. Wzrost ciśnienia tętniczego jest wykrywany przez baroreceptory, odrębny system czuciowy niezwiązany z chemoreceptorami centralnymi. Stężenie glukozy w płynie mózgowo-rdzeniowym nie jest głównym bodźcem dla centralnych chemoreceptorów oddechowych. Temperatura krwi jest monitorowana przez ośrodek termoregulacji w podwzgórzu, odrębny od chemoreceptorów oddechowych pnia mózgu." },
    { oldQ: 'Prawidłowa luka anionowa w kwasicy metabolicznej sugeruje jaką przyczynę:', q: 'Prawidłowa luka anionowa przy kwasicy metabolicznej sugeruje jaką przyczynę?', o: ['utratę wodorowęglanów, np. przez biegunkę lub niedobór aldosteronu', 'kwasicę mleczanową', 'kwasicę ketonową (cukrzycową)', 'zatrucie metanolem', 'zatrucie glikolem etylenowym'], a: 0, rationale: "Poprawnie: kwasica metaboliczna z prawidłową luką anionową (hiperchloremiczna) wynika z utraty wodorowęglanów (np. biegunka) lub zaburzeń wydalania kwasów (np. niedobór aldosteronu, kwasica cewkowa nerkowa) — utracone HCO3- są zastępowane chlorkami, nie 'niemierzonymi' anionami. Kwasica mleczanowa daje ZWIĘKSZONĄ lukę anionową, ponieważ mleczan jest niemierzonym anionem gromadzącym się we krwi. Kwasica ketonowa daje zwiększoną lukę anionową z powodu gromadzenia się ciał ketonowych (niemierzonych anionów). Zatrucie metanolem daje zwiększoną lukę anionową z powodu powstawania kwasu mrówkowego, niemierzonego aniony. Zatrucie glikolem etylenowym daje zwiększoną lukę anionową z powodu toksycznych metabolitów kwasowych, będących niemierzonymi anionami." },
    { oldQ: 'Które rodzaje krwawień są typowe dla trombocytopenii, a które dla skazy osoczowej:', q: 'Które rodzaje krwawień są typowe dla trombocytopenii (skazy płytkowej), a które dla skazy osoczowej?', o: ['trombocytopenia — krwawienia z nosa, dróg moczowych, przewodu pokarmowego, podpajęczynówkowe; skaza osoczowa — krwawienia dostawowe', 'trombocytopenia — krwawienia dostawowe; skaza osoczowa — krwawienia z nosa i błon śluzowych', 'oba typy skaz dają identyczny, nierozróżnialny obraz kliniczny krwawień', 'trombocytopenia — wyłącznie krwawienia wewnątrzczaszkowe; skaza osoczowa — wyłącznie krwawienia skórne', 'trombocytopenia — krwawienia głębokie do mięśni; skaza osoczowa — wybroczyny skórne'], a: 0, rationale: "Poprawnie: trombocytopenia daje typowo krwawienia powierzchowne, śluzówkowe (nos, drogi moczowe, przewód pokarmowy) oraz podpajęczynówkowe, natomiast skaza osoczowa (np. hemofilia) daje klasyczne krwawienia dostawowe (hemartrozy) i głębokie krwiaki tkankowe. Zamiana tych wzorców (opcja B) odwraca kliniczne rozróżnienie między tymi typami skaz krwotocznych. Obrazy kliniczne tych dwóch typów skaz wyraźnie się różnią, co jest podstawą ich klinicznego różnicowania — nie są identyczne. Ograniczenie trombocytopenii wyłącznie do krwawień wewnątrzczaszkowych i skazy osoczowej wyłącznie do skórnych znacznie zawęża i zniekształca rzeczywisty, szerszy obraz kliniczny obu jednostek. To właśnie skaza osoczowa (nie płytkowa) daje typowo krwawienia głębokie do mięśni/stawów, a wybroczyny skórne są bardziej typowe dla skazy płytkowej — ta opcja odwraca przypisanie." },
    { oldQ: 'Wskaż strukturę, z której wychodzi dyspozycja rozpoczęcia dowolnego skurczu mięśnia:', q: 'Wskaż strukturę mózgu, z której wychodzi dyspozycja (rozkaz) rozpoczęcia dowolnego skurczu mięśnia szkieletowego.', o: ['zakręt przedśrodkowy kory mózgu (pierwszorzędowa kora ruchowa)', 'zakręt zaśrodkowy kory mózgu (pierwszorzędowa kora czuciowa)', 'płat potyliczny kory mózgu', 'móżdżek jako główny inicjator ruchu dowolnego', 'wzgórze jako główny inicjator ruchu dowolnego'], a: 0, rationale: "Poprawnie: zakręt przedśrodkowy (pierwszorzędowa kora ruchowa, pole 4 Brodmanna) jest strukturą korową, z której wychodzi bezpośrednia dyspozycja inicjująca dowolny skurcz mięśnia szkieletowego, poprzez drogę korowo-rdzeniową. Zakręt zaśrodkowy jest pierwszorzędową korą CZUCIOWĄ, odbierającą informacje somatosensoryczne, a nie inicjującą ruch. Płat potyliczny odpowiada za przetwarzanie informacji wzrokowej, niezwiązany z inicjacją ruchu dowolnego. Móżdżek koordynuje i precyzuje ruch (płynność, równowagę), ale nie jest głównym inicjatorem świadomej dyspozycji ruchowej — tę rolę pełni kora ruchowa. Wzgórze pełni funkcję przekaźnikową dla sygnałów czuciowych i częściowo ruchowych, ale nie jest pierwotnym źródłem świadomej dyspozycji ruchu dowolnego." },
    { oldQ: 'Baroreceptory zatoki tętnicy szyjnej unerwione są przez:', q: 'Baroreceptory zatoki tętnicy szyjnej są unerwione przez jaki nerw?', o: ['nerw zatokowy, gałązkę nerwu językowo-gardłowego (IX)', 'nerw błędny (X) bezpośrednio, bez pośrednictwa innych nerwów', 'nerw trójdzielny (V)', 'nerw twarzowy (VII)', 'nerw podjęzykowy (XII)'], a: 0, rationale: "Poprawnie: baroreceptory zatoki tętnicy szyjnej są unerwione przez nerw zatokowy (Heringa), będący gałązką nerwu językowo-gardłowego (IX), z ciałami neuronów w zwoju skalistym. Nerw błędny (X) unerwia baroreceptory ŁUKU AORTY, nie zatoki szyjnej — to inna lokalizacja anatomiczna z odrębnym unerwieniem. Nerw trójdzielny (V) odpowiada głównie za czucie twarzy i niektóre funkcje żucia, niezwiązane z baroreceptorami naczyniowymi. Nerw twarzowy (VII) odpowiada głównie za mimikę twarzy i częściowo smak, niezwiązany z unerwieniem baroreceptorów szyjnych. Nerw podjęzykowy (XII) unerwia ruchowo mięśnie języka, niezwiązany z baroreceptorami naczyniowymi." },
    { oldQ: 'Uszkodzenie mięśnia sercowego uruchamia mechanizmy homeostatyczne powodujące:', q: 'Uszkodzenie mięśnia sercowego uruchamia mechanizmy homeostatyczne powodujące jakie zmiany?', o: ['zwiększenie obciążenia wstępnego (preload) i częstości skurczów serca', 'zmniejszenie obciążenia wstępnego i częstości skurczów serca', 'zmniejszenie aktywności układu współczulnego', 'zahamowanie układu renina-angiotensyna-aldosteron', 'natychmiastowe zmniejszenie objętości krwi krążącej'], a: 0, rationale: "Poprawnie: uszkodzenie mięśnia sercowego (spadek rzutu serca) aktywuje mechanizmy kompensacyjne — pobudzenie współczulne zwiększa częstość akcji serca, a retencja sodu i wody (poprzez RAA) zwiększa obciążenie wstępne, próbując utrzymać rzut minutowy. Zmniejszenie preload i częstości skurczów byłoby sprzeczne z kompensacyjną naturą tych mechanizmów — organizm dąży do ZWIĘKSZENIA tych parametrów, by utrzymać perfuzję tkanek. Uszkodzenie serca AKTYWUJE, a nie hamuje układ współczulny — to kluczowy mechanizm kompensacyjny w niewydolności serca. Uszkodzenie mięśnia sercowego AKTYWUJE (nie hamuje) układ RAA, co jest istotnym elementem patofizjologii niewydolności serca. Mechanizmy homeostatyczne dążą do ZWIĘKSZENIA, a nie zmniejszenia objętości krwi krążącej, poprzez retencję sodu i wody." },
    { oldQ: 'Który z czynników inicjuje wewnątrzpochodną kaskadę krzepnięcia:', q: 'Który z czynników krzepnięcia inicjuje wewnątrzpochodną (śródpochodną) kaskadę krzepnięcia?', o: ['czynnik XII', 'czynnik III (tromboplastyna tkankowa)', 'czynnik VII', 'czynnik X', 'czynnik II (protrombina)'], a: 0, rationale: "Poprawnie: czynnik XII (czynnik Hagemana), aktywowany przez kontakt z odsłoniętym kolagenem uszkodzonego naczynia, inicjuje drogę wewnątrzpochodną kaskady krzepnięcia. Czynnik III (tromboplastyna tkankowa) inicjuje drogę ZEWNĄTRZPOCHODNĄ, odrębny szlak kaskady krzepnięcia. Czynnik VII łączy się z czynnikiem tkankowym, inicjując drogę zewnątrzpochodną, nie wewnątrzpochodną. Czynnik X jest wspólnym punktem, w którym łączą się obie drogi krzepnięcia (droga wspólna), ale nie jest czynnikiem inicjującym drogę wewnątrzpochodną. Czynnik II (protrombina) jest przekształcany w trombinę w końcowym etapie kaskady krzepnięcia, nie jest czynnikiem inicjującym drogę wewnątrzpochodną." },
    { oldQ: 'Wskaż prawidłową parę inhibitor krzepnięcia — czynnik, na który działa:', q: 'Wskaż prawidłową parę: inhibitor krzepnięcia — czynnik krzepnięcia, na który działa.', o: ['trombomodulina hamuje trombinę (czynnik IIa)', 'antytrombina III nie hamuje żadnego czynnika krzepnięcia', 'białko C aktywuje czynniki Va i VIIIa zamiast je hamować', 'plazmina hamuje wyłącznie czynnik XII', 'heparyna aktywuje trombinę zamiast ją hamować'], a: 0, rationale: "Poprawnie: trombomodulina, białko na powierzchni śródbłonka, wiąże trombinę (czynnik IIa) i zmienia jej funkcję na antykoagulacyjną (aktywację białka C), efektywnie hamując prokoagulacyjne działanie trombiny. Antytrombina III jest kluczowym, dobrze udokumentowanym inhibitorem krzepnięcia, hamującym trombinę i czynnik Xa — twierdzenie, że nie hamuje żadnego czynnika, jest sprzeczne z jej podstawową funkcją. Aktywowane białko C INAKTYWUJE (rozkłada), a nie aktywuje, czynniki Va i VIIIa — to odwrócenie rzeczywistego mechanizmu antykoagulacyjnego. Plazmina rozkłada FIBRYNĘ (a nie hamuje czynnik XII), będąc głównym enzymem fibrynolizy, odrębnym mechanizmem od hamowania czynników krzepnięcia. Heparyna nasila (nie hamuje bezpośrednio) działanie antytrombiny III, która z kolei HAMUJE trombinę — twierdzenie o aktywacji trombiny przez heparynę jest sprzeczne z jej antykoagulacyjnym działaniem." },
    { oldQ: 'Efekt niedoboru 21-hydroksylazy — zmiany stężenia ACTH i androgenów:', q: 'Jaki jest efekt niedoboru 21-hydroksylazy w zakresie stężenia ACTH i androgenów?', o: ['przerost kory nadnerczy, podwyższone stężenie ACTH i androgenów', 'zanik kory nadnerczy, obniżone stężenie ACTH i androgenów', 'przerost kory nadnerczy, obniżone stężenie ACTH przy podwyższonych androgenach', 'prawidłowa wielkość nadnerczy, prawidłowe stężenie ACTH i androgenów', 'przerost kory nadnerczy, podwyższone ACTH przy obniżonych androgenach'], a: 0, rationale: "Poprawnie: niedobór 21-hydroksylazy upośledza syntezę kortyzolu, co poprzez brak hamowania zwrotnego zwiększa wydzielanie ACTH, prowadząc do przerostu kory nadnerczy i przesunięcia steroidogenezy w kierunku nadprodukcji androgenów (wrodzony przerost nadnerczy). Zanik kory nadnerczy z obniżonym ACTH i androgenami opisuje odwrotny, nieprawidłowy mechanizm — w tym niedoborze dochodzi do przerostu, nie zaniku, i podwyższenia, nie obniżenia tych parametrów. Podwyższenie ACTH przy przeroście jest prawidłowe, ale androgeny są w tym zaburzeniu PODWYŻSZONE (nie obniżone) z powodu przekierowania steroidogenezy. Zaburzenie to daje istotne, wyraźne zmiany hormonalne i strukturalne — stwierdzenie o prawidłowych wartościach jest sprzeczne z istotą tej choroby. ACTH jest podwyższone (prawidłowo), ale androgeny są RÓWNIEŻ podwyższone, nie obniżone — to kluczowa cecha tego zaburzenia steroidogenezy." },
    { oldQ: 'Mediatory odpowiedzialne za uogólnioną reakcję zapalną, produkowane przez makrofagi:', q: 'Jakie mediatory odpowiedzialne za uogólnioną (systemową) reakcję zapalną są produkowane przez makrofagi?', o: ['IL-1 i TNF-α', 'insulina i glukagon', 'aldosteron i kortyzol', 'erytropoetyna i trombopoetyna', 'kwasy żółciowe i bilirubina'], a: 0, rationale: "Poprawnie: IL-1 i TNF-α, produkowane przez aktywowane makrofagi, są kluczowymi cytokinami prozapalnymi odpowiedzialnymi za uogólnioną reakcję zapalną, w tym gorączkę i indukcję białek ostrej fazy. Insulina i glukagon są hormonami trzustkowymi regulującymi metabolizm glukozy, niezwiązanymi z produkcją przez makrofagi ani z inicjacją uogólnionej reakcji zapalnej. Aldosteron i kortyzol są hormonami steroidowymi kory nadnerczy, niezwiązanymi z produkcją makrofagów. Erytropoetyna i trombopoetyna są hormonami regulującymi hematopoezę, produkowanymi głównie przez nerki/wątrobę, niezwiązanymi z odpowiedzią zapalną makrofagów. Kwasy żółciowe i bilirubina są produktami metabolizmu wątrobowego, niezwiązanymi z mediatorami zapalnymi produkowanymi przez makrofagi." },
    { oldQ: 'Charakterystyczna zmiana EKG dla bloku odnogi pęczka Hisa (RBBB lub LBBB):', q: 'Jaka jest charakterystyczna zmiana w EKG dla bloku odnogi pęczka Hisa (RBBB lub LBBB)?', o: ['wydłużenie czasu trwania depolaryzacji komór (poszerzenie zespołu QRS powyżej 120 ms)', 'skrócenie odstępu PQ poniżej 120 ms', 'wydłużenie odstępu PQ powyżej 200 ms', 'uniesienie odcinka ST we wszystkich odprowadzeniach', 'skrócenie odstępu QT poniżej normy'], a: 0, rationale: "Poprawnie: blok odnogi pęczka Hisa opóźnia aktywację jednej z komór, wydłużając czas trwania depolaryzacji komór i poszerzając zespół QRS powyżej 120 ms — to podstawowe kryterium rozpoznania bloku odnogi. Skrócenie PQ poniżej 120 ms jest typowe dla zespołu preekscytacji (np. WPW), niezwiązanego z blokiem odnogi pęczka Hisa. Wydłużenie PQ powyżej 200 ms to definicja bloku AV I stopnia, odrębnego zaburzenia przewodzenia dotyczącego przewodzenia przedsionek-komora, nie samej depolaryzacji komór. Uniesienie ST we wszystkich odprowadzeniach nie jest charakterystyczną cechą bloku odnogi, lecz sugerowałoby np. zapalenie osierdzia lub rozległy zawał. Skrócenie QT nie jest typową cechą bloku odnogi pęczka Hisa — poszerzenie QRS w ramach bloku odnogi zwykle raczej WYDŁUŻA odstęp QT." },
    { oldQ: 'Jaki mechanizm w największym stopniu przyczynia się do wzrostu ciśnienia w tętnicy płucnej w zespole hipowentylacji otyłych:', q: 'Jaki mechanizm w największym stopniu przyczynia się do wzrostu ciśnienia w tętnicy płucnej w zespole hipowentylacji otyłych?', o: ['skurcz naczyń płucnych pod wpływem hipoksemii pęcherzykowej', 'rozszerzenie naczyń płucnych pod wpływem hiperkapnii', 'zmniejszenie objętości krwi krążącej w krążeniu płucnym', 'wzrost podatności naczyń płucnych', 'zmniejszenie lepkości krwi w krążeniu płucnym'], a: 0, rationale: "Poprawnie: przewlekła hipoksemia pęcherzykowa (na skutek hipowentylacji związanej z otyłością) wywołuje odruchowy skurcz naczyń płucnych (odwrotny do reakcji w krążeniu systemowym), co prowadzi do nadciśnienia płucnego i serca płucnego. Rozszerzenie naczyń pod wpływem hiperkapnii jest sprzeczne z rzeczywistym mechanizmem — hipoksemia pęcherzykowa wywołuje SKURCZ, nie rozszerzenie naczyń płucnych. Zmniejszenie objętości krwi w krążeniu płucnym nie jest głównym mechanizmem wzrostu ciśnienia — wręcz przeciwnie, zwiększony opór naczyniowy przy zachowanym/zwiększonym przepływie podnosi ciśnienie. Wzrost podatności naczyń (rozciągliwości) obniżałby, a nie podnosił ciśnienie w tętnicy płucnej — to odwrócenie mechanizmu, gdyż w rzeczywistości dochodzi do zwężenia, nie rozciągnięcia naczyń. Lepkość krwi może wzrastać (wtórna policytemia w hipoksemii), ale nie jest to głównym, dominującym mechanizmem wzrostu ciśnienia płucnego w tym zespole — dominuje skurcz naczyń." },
    { oldQ: 'Ile procent pojemności minutowej lewej komory stanowi pojemność minutowa prawej komory:', q: 'Ile procent rzutu minutowego lewej komory stanowi fizjologicznie rzut minutowy prawej komory?', o: ['100% (rzuty minutowe obu komór są sobie równe)', 'ok. 50%, ponieważ prawa komora pompuje mniejszą objętość', 'ok. 150%, ponieważ prawa komora pompuje więcej krwi', 'zależy wyłącznie od chwilowej częstości akcji serca, bez stałej proporcji', 'ok. 75%, z powodu fizjologicznego przecieku międzykomorowego'], a: 0, rationale: "Poprawnie: krążenie systemowe i płucne są połączone szeregowo, więc w warunkach fizjologicznych rzuty minutowe obu komór muszą być sobie równe (100%) — inaczej doszłoby do postępującego gromadzenia się krwi w jednym z krążeń. Wartość 50% sugerowałaby, że prawa komora pompuje o połowę mniej krwi, co prowadziłoby do narastającego przekrwienia w krążeniu systemowym — sytuacja niefizjologiczna. Wartość 150% sugerowałaby odwrotną nierównowagę, prowadzącą do zastoju w krążeniu płucnym — również niefizjologiczna w warunkach prawidłowych. Rzuty minutowe obu komór pozostają sobie równe niezależnie od chwilowej częstości akcji serca — to stała zależność wynikająca z szeregowego połączenia krążeń. Fizjologicznie nie istnieje przeciek międzykomorowy (byłby to stan patologiczny, np. ubytek przegrody międzykomorowej), więc 75% nie odzwierciedla warunków prawidłowych." },
    { oldQ: 'Które zaburzenie mieszane równowagi kwasowo-zasadowej nie jest fizjologicznie możliwe:', q: 'Które zaburzenie mieszane równowagi kwasowo-zasadowej nie jest fizjologicznie możliwe do jednoczesnego wystąpienia?', o: ['jednoczesna kwasica i zasadowica oddechowa', 'jednoczesna kwasica oddechowa i kwasica metaboliczna', 'jednoczesna zasadowica oddechowa i zasadowica metaboliczna', 'jednoczesna kwasica metaboliczna i zasadowica oddechowa', 'jednoczesna zasadowica metaboliczna i kwasica oddechowa'], a: 0, rationale: "Poprawnie: kwasica i zasadowica oddechowa nie mogą wystąpić jednocześnie, ponieważ oznaczałoby to, że płuca jednocześnie hipowentylują (retencja CO2, kwasica) i hiperwentylują (utrata CO2, zasadowica) — stan fizjologicznie niemożliwy, gdyż wentylacja pęcherzykowa w danym momencie ma tylko jeden kierunek zmiany pCO2. Kwasica oddechowa i metaboliczna mogą współistnieć (np. w zatrzymaniu krążenia) — są to zaburzenia niezależnych mechanizmów (wentylacja i metabolizm) i mogą się nakładać, potęgując kwasicę. Zasadowica oddechowa i metaboliczna mogą współistnieć (np. hiperwentylacja przy wymiotach) — również niezależne mechanizmy, mogące się nakładać. Kwasica metaboliczna i zasadowica oddechowa mogą współistnieć (np. kompensacja lub niezależne procesy jednocześnie), będąc możliwą kombinacją zaburzeń z różnych osi (metabolicznej i oddechowej). Zasadowica metaboliczna i kwasica oddechowa mogą również współistnieć, będąc niezależnymi od siebie procesami mogącymi wystąpić jednocześnie." },
    { oldQ: 'Gruczoły Lieberkühna wytwarzają:', q: 'Co wytwarzają gruczoły (krypty) Lieberkühna jelita?', o: ['sok jelitowy', 'żółć', 'sok trzustkowy', 'kwas solny', 'śluz żołądkowy'], a: 0, rationale: "Poprawnie: gruczoły (krypty) Lieberkühna, zlokalizowane w błonie śluzowej jelita cienkiego i grubego, wytwarzają sok jelitowy, zawierający enzymy i elektrolity wspomagające trawienie i wchłanianie. Żółć jest produkowana przez wątrobę i magazynowana w pęcherzyku żółciowym, niezwiązana z gruczołami Lieberkühna. Sok trzustkowy jest wytwarzany przez trzustkę, odrębny narząd niezwiązany z kryptami jelitowymi. Kwas solny jest wydzielany przez komórki okładzinowe żołądka, niezwiązane z gruczołami Lieberkühna jelita. Śluz żołądkowy jest wydzielany przez komórki błony śluzowej żołądka, odrębne struktury od krypt jelitowych." },
    { oldQ: 'Smoliste stolce są objawem czego:', q: 'Smoliste, czarne stolce (melena) są typowym objawem czego?', o: ['krwawienia z górnego odcinka przewodu pokarmowego', 'krwawienia z dolnego odcinka przewodu pokarmowego (np. odbytnicy)', 'biegunki tłuszczowej z zaburzeń wchłaniania', 'zaparcia nawykowego bez utraty krwi', 'zakażenia pasożytniczego jelita cienkiego bez krwawienia'], a: 0, rationale: "Poprawnie: smoliste, czarne stolce (melena) powstają, gdy krew z krwawienia w górnym odcinku przewodu pokarmowego (żołądek, dwunastnica) ulega trawieniu przez enzymy i kwas żołądkowy podczas pasażu jelitowego, przybierając charakterystyczną czarną barwę. Krwawienie z dolnego odcinka przewodu pokarmowego (np. odbytnicy) daje typowo krew jasnoczerwoną (krwawienie per rectum), niezmienioną przez trawienie, a nie smoliste stolce. Biegunka tłuszczowa daje charakterystyczne, tłuste, cuchnące stolce, niezwiązane z obecnością strawionej krwi. Zaparcie nawykowe bez utraty krwi nie daje charakterystycznego, czarnego zabarwienia stolca związanego z krwią. Zakażenie pasożytnicze bez krwawienia nie powoduje typowo smolistego zabarwienia stolca, które jest swoiście związane z obecnością strawionej krwi." },
    { oldQ: 'Główna przyczyna niedokrwistości w przewlekłej chorobie nerek:', q: 'Jaka jest główna przyczyna niedokrwistości w przewlekłej chorobie nerek?', o: ['niedobór erytropoetyny', 'niedobór żelaza jako jedyna przyczyna', 'niedobór witaminy B12', 'nadmierna hemoliza erytrocytów', 'niedobór kwasu foliowego'], a: 0, rationale: "Poprawnie: uszkodzenie miąższu nerek zmniejsza produkcję erytropoetyny, hormonu niezbędnego do stymulacji erytropoezy w szpiku, co jest głównym, dominującym mechanizmem niedokrwistości w przewlekłej chorobie nerek. Niedobór żelaza może współistnieć i nasilać niedokrwistość nerkopochodną, ale nie jest jej główną, pierwotną przyczyną — kluczowy jest brak EPO. Niedobór witaminy B12 jest odrębną przyczyną niedokrwistości (megaloblastycznej), niezwiązaną bezpośrednio z patofizjologią przewlekłej choroby nerek. Nadmierna hemoliza nie jest głównym mechanizmem niedokrwistości nerkopochodnej — dominuje niedostateczna produkcja, nie nadmierny rozpad erytrocytów. Niedobór kwasu foliowego jest odrębną przyczyną niedokrwistości megaloblastycznej, niebędącą główną, charakterystyczną przyczyną anemii w przewlekłej chorobie nerek." },
    { oldQ: 'Gdzie odbywa się spermatogeneza i od czego jest zależna:', q: 'Gdzie odbywa się spermatogeneza i od jakich hormonów jest zależna?', o: ['w kanalikach plemnikotwórczych jądra; zależna od FSH i testosteronu', 'w najądrzu; zależna wyłącznie od LH', 'w gruczole krokowym; zależna od estrogenów', 'w kanalikach plemnikotwórczych jądra; zależna wyłącznie od prolaktyny', 'w pęcherzykach nasiennych; zależna od progesteronu'], a: 0, rationale: "Poprawnie: spermatogeneza zachodzi w kanalikach plemnikotwórczych jądra, będąc regulowana przez FSH (działający na komórki Sertoliego) oraz testosteron (produkowany przez komórki Leydiga pod wpływem LH). Najądrze jest miejscem dojrzewania i magazynowania plemników PO zakończeniu spermatogenezy w jądrze, nie miejscem samego procesu spermatogenezy. Gruczoł krokowy produkuje część płynu nasiennego, nie jest miejscem spermatogenezy, a estrogeny nie są głównym regulatorem tego procesu u mężczyzn. Prolaktyna nie jest głównym regulatorem spermatogenezy — kluczowe są FSH i testosteron, a nadmiar prolaktyny może wręcz zaburzać funkcje rozrodcze. Pęcherzyki nasienne produkują część płynu nasiennego, nie są miejscem spermatogenezy, a progesteron nie jest głównym regulatorem tego procesu u mężczyzn." },
    { oldQ: 'Nerw trzewny (odgałęzienie pnia współczulnego) a przepływ krwi przez wątrobę:', q: 'Jaki wpływ na przepływ krwi przez wątrobę ma pobudzenie nerwu trzewnego (odgałęzienia pnia współczulnego)?', o: ['zmniejsza przepływ krwi przez wątrobę', 'zwiększa przepływ krwi przez wątrobę', 'nie ma żadnego wpływu na przepływ krwi przez wątrobę', 'zwiększa przepływ wyłącznie przez żyłę wrotną, bez wpływu na tętnicę wątrobową', 'całkowicie zatrzymuje przepływ krwi przez wątrobę'], a: 0, rationale: "Poprawnie: pobudzenie współczulne poprzez nerw trzewny powoduje skurcz naczyń trzewnych, w tym naczyń zaopatrujących wątrobę, zmniejszając przepływ krwi przez ten narząd (np. w reakcji stresowej, przekierowującej krew do mięśni i serca). Twierdzenie o zwiększeniu przepływu jest odwróceniem rzeczywistego, obkurczającego działania pobudzenia współczulnego na krążenie trzewne. Nerw trzewny ma istotny, dobrze udokumentowany wpływ na krążenie wątrobowe, więc stwierdzenie braku wpływu jest nieprawdziwe. Pobudzenie współczulne wpływa na CAŁE unaczynienie wątroby (zarówno żyłę wrotną, jak i tętnicę wątrobową), a nie wybiórczo tylko na jedno z tych naczyń. Pobudzenie współczulne zmniejsza, ale nie zatrzymuje całkowicie przepływu krwi przez wątrobę — narząd zachowuje pewien przepływ podstawowy nawet przy silnej stymulacji współczulnej." },
    { oldQ: 'Z czym związany jest odruch żołądkowo-krętniczy:', q: 'Z czym jest związany odruch żołądkowo-krętniczy?', o: ['z otwieraniem zastawki krętniczo-kątniczej z chwilą rozpoczęcia opróżniania się żołądka', 'z zamykaniem zastawki krętniczo-kątniczej z chwilą wypełnienia się żołądka pokarmem', 'z hamowaniem perystaltyki jelita krętego po posiłku', 'z pobudzeniem wydzielania kwasu solnego w żołądku po rozciągnięciu jelita krętego', 'z hamowaniem wydzielania żółci po posiłku'], a: 0, rationale: "Poprawnie: odruch żołądkowo-krętniczy polega na tym, że rozpoczęcie opróżniania żołądka (przemieszczanie treści pokarmowej dalej) nasila perystaltykę jelita krętego i otwiera zastawkę krętniczo-kątniczą, ułatwiając przechodzenie treści do jelita grubego. Zamykanie zastawki przy wypełnieniu żołądka jest odwróceniem rzeczywistego mechanizmu — to opróżnianie żołądka, nie jego wypełnienie, wyzwala ten odruch, i skutkuje OTWARCIEM, nie zamknięciem zastawki. Odruch ten NASILA, a nie hamuje, perystaltykę jelita krętego — to odwrócenie rzeczywistego kierunku działania odruchu. Odruch ten dotyczy motoryki jelitowej (perystaltyki i zastawki), nie wydzielania kwasu solnego w żołądku. Odruch żołądkowo-krętniczy nie jest związany z hamowaniem wydzielania żółci — dotyczy motoryki jelita krętego i zastawki krętniczo-kątniczej." },
    { oldQ: 'Peptyd wywołujący reakcję immunologiczną w celiakii:', q: 'Jaki peptyd wywołuje reakcję immunologiczną w celiakii?', o: ['gliadyna (frakcja glutenu)', 'kazeina (białko mleka)', 'owoalbumina (białko jaja)', 'insulina', 'kolagen typu II'], a: 0, rationale: "Poprawnie: gliadyna, frakcja glutenu obecna w pszenicy, jęczmieniu i życie, wywołuje w celiakii nieprawidłową odpowiedź immunologiczną prowadzącą do uszkodzenia kosmków jelitowych. Kazeina jest białkiem mleka związanym z alergią pokarmową na mleko, niezwiązaną z mechanizmem celiakii. Owoalbumina jest białkiem jaja kurzego, związanym z alergią na jaja, odrębną jednostką od celiakii. Insulina jest hormonem trzustkowym, niezwiązanym z mechanizmem immunologicznym celiakii. Kolagen typu II jest białkiem tkanki łącznej związanym z niektórymi chorobami autoimmunologicznymi stawów (np. reumatoidalnym zapaleniem stawów), niezwiązanym z celiakią." },
    { oldQ: 'Stężenie którego czynnika krzepnięcia zależnego od witaminy K obniża się najszybciej po rozpoczęciu leczenia antagonistami witaminy K:', q: 'Stężenie którego czynnika krzepnięcia zależnego od witaminy K obniża się najszybciej po rozpoczęciu leczenia antagonistami witaminy K (np. warfaryną)?', o: ['czynnika VII (ma najkrótszy okres półtrwania spośród II, VII, IX, X)', 'czynnika II — protrombiny (ma najdłuższy okres półtrwania)', 'czynnika IX', 'czynnika X', 'wszystkie cztery czynniki obniżają się jednocześnie z tą samą szybkością'], a: 0, rationale: "Poprawnie: czynnik VII ma najkrótszy okres półtrwania spośród czynników zależnych od witaminy K (II, VII, IX, X), dlatego jego stężenie obniża się najszybciej po rozpoczęciu terapii antagonistami witaminy K, co odzwierciedla wczesny wzrost INR. Czynnik II (protrombina) ma najdłuższy okres półtrwania spośród tych czynników, więc jego stężenie obniża się najwolniej, nie najszybciej. Czynnik IX ma pośredni okres półtrwania, dłuższy niż czynnik VII, więc nie obniża się najszybciej. Czynnik X ma również dłuższy okres półtrwania niż czynnik VII, więc jego spadek następuje wolniej. Czynniki te mają wyraźnie różne okresy półtrwania, dlatego nie obniżają się jednocześnie z tą samą szybkością — to podstawa klinicznego znaczenia szybkiego wzrostu INR na początku terapii." },
    { oldQ: 'Zmniejszenie sprężystości płuc w przebiegu rozedmy powoduje jakie zmiany klatki piersiowej i FRC:', q: 'Zmniejszenie sprężystości (elastyczności) płuc w przebiegu rozedmy powoduje jakie zmiany klatki piersiowej i czynnościowej pojemności zalegającej (FRC)?', o: ['rozszerzenie klatki piersiowej ("klatka beczkowata") i zwiększenie FRC', 'zapadnięcie klatki piersiowej i zmniejszenie FRC', 'brak jakichkolwiek zmian klatki piersiowej i FRC', 'rozszerzenie klatki piersiowej, ale zmniejszenie FRC', 'zapadnięcie klatki piersiowej, ale zwiększenie FRC'], a: 0, rationale: "Poprawnie: utrata sprężystości płuc w rozedmie osłabia siłę elastycznej retrakcji, pozwalając płucom (i klatce piersiowej) pozostawać w stanie nadmiernego rozdęcia, co daje charakterystyczną 'klatkę beczkowatą' i istotny wzrost FRC (powietrze uwięzione w płucach). Zapadnięcie klatki piersiowej ze zmniejszeniem FRC opisuje raczej mechanizm restrykcyjny/niedodmę, przeciwny do rozedmy. Rozedma powoduje wyraźne, dobrze udokumentowane zmiany strukturalne i czynnościowe — stwierdzenie braku zmian jest nieprawdziwe. Rozszerzenie klatki piersiowej w rozedmie idzie w parze ze WZROSTEM, nie spadkiem FRC — te dwie zmiany są ze sobą spójne, nie rozbieżne. Zapadnięcie klatki piersiowej przy jednoczesnym wzroście FRC jest wewnętrznie sprzeczne — nadmierne rozdęcie płuc (wzrost FRC) wiąże się z rozszerzeniem, nie zapadnięciem klatki piersiowej." },
    { oldQ: 'We wrzecionku nerwowo-mięśniowym motoneuron α unerwia ruchowo:', q: 'We wrzecionku nerwowo-mięśniowym motoneuron α unerwia ruchowo jaki rodzaj włókien?', o: ['komórki ekstrafuzalne (mięsień szkieletowy właściwy, poza wrzecionkiem)', 'komórki intrafuzalne wewnątrz wrzecionka nerwowo-mięśniowego', 'wyłącznie włókna czuciowe grupy Ia', 'wyłącznie włókna czuciowe grupy II', 'torebkę łącznotkankową otaczającą wrzecionko'], a: 0, rationale: "Poprawnie: motoneuron α unerwia ruchowo komórki ekstrafuzalne — właściwe włókna mięśnia szkieletowego znajdujące się poza wrzecionkiem, odpowiedzialne za generowanie siły skurczu całego mięśnia. Komórki intrafuzalne (wewnątrz wrzecionka) są unerwiane ruchowo przez motoneurony GAMMA (γ), odrębny typ neuronów ruchowych regulujących czułość wrzecionka. Włókna czuciowe grupy Ia są elementem AFERENTNYM (czuciowym) wrzecionka, przekazującym informację o rozciągnięciu, a nie strukturą unerwianą ruchowo przez motoneuron α. Włókna czuciowe grupy II są dodatkowym elementem czuciowym wrzecionka, również aferentnym, nie efektorem unerwienia ruchowego motoneuronu α. Torebka łącznotkankowa jest strukturą podporową wrzecionka, niebędącą tkanką kurczliwą unerwianą ruchowo." },
    { oldQ: 'Niedobór czynnika VIII wiąże się z jaką chorobą:', q: 'Niedobór czynnika VIII krzepnięcia wiąże się z jaką chorobą?', o: ['hemofilią A', 'hemofilią B', 'chorobą von Willebranda jako jedyną przyczyną', 'niedoborem witaminy K', 'zespołem DIC jako jedyną przyczyną'], a: 0, rationale: "Poprawnie: niedobór czynnika VIII jest przyczyną hemofilii A, klasycznej, dziedzicznej, sprzężonej z chromosomem X skazy krwotocznej. Hemofilia B wynika z niedoboru czynnika IX, nie VIII — to zamiana czynników odpowiadających poszczególnym typom hemofilii. Choroba von Willebranda wynika z niedoboru/dysfunkcji czynnika von Willebranda, choć wtórnie może obniżać stabilność czynnika VIII — nie jest to jednak jedyna ani bezpośrednia przyczyna niedoboru czynnika VIII, jaką jest hemofilia A. Niedobór witaminy K wpływa na czynniki II, VII, IX i X, nie na czynnik VIII, który nie jest zależny od witaminy K. DIC jest zespołem nabytym, zużywającym wiele czynników krzepnięcia jednocześnie, a nie izolowanym, wrodzonym niedoborem czynnika VIII." },
    { oldQ: 'Jaki jest wpływ silnego oświetlenia na siatkówkę:', q: 'Jaki jest wpływ długotrwałego, silnego oświetlenia na wrażliwość siatkówki?', o: ['podwyższa próg wrażliwości siatkówki (adaptacja do światła)', 'obniża próg wrażliwości siatkówki, zwiększając jej czułość', 'nie wpływa na próg wrażliwości siatkówki', 'powoduje trwałe, nieodwracalne uszkodzenie wszystkich fotoreceptorów', 'natychmiastowo i trwale znosi zdolność widzenia barw'], a: 0, rationale: "Poprawnie: silne, długotrwałe oświetlenie powoduje adaptację do światła, podwyższając próg pobudliwości siatkówki (zmniejszając jej czułość), co zapobiega przeciążeniu układu wzrokowego przy dużym natężeniu światła. Obniżenie progu (zwiększenie czułości) jest typowe dla adaptacji do CIEMNOŚCI, procesu przeciwnego do adaptacji do silnego światła. Silne oświetlenie ma istotny, dobrze udokumentowany wpływ na wrażliwość siatkówki poprzez mechanizm adaptacji, więc stwierdzenie braku wpływu jest nieprawdziwe. Fizjologiczna adaptacja do światła jest procesem odwracalnym, niepowodującym trwałego uszkodzenia fotoreceptorów w normalnych warunkach oświetleniowych. Adaptacja do światła nie znosi trwale zdolności widzenia barw — to odwracalny, fizjologiczny mechanizm dostosowania czułości, nie patologia widzenia barwnego." },
    { oldQ: 'Ludzka gonadotropina kosmówkowa (hCG) — trzy prawdziwe cechy działania:', q: 'Które trzy cechy prawidłowo opisują działanie ludzkiej gonadotropiny kosmówkowej (hCG)?', o: ['naśladuje działanie LH, pobudza komórki Leydiga do wydzielania testosteronu, jest stosowana w teście oceniającym zdolność jąder do biosyntezy testosteronu', 'naśladuje działanie FSH, hamuje komórki Leydiga, jest stosowana w diagnostyce niewydolności tarczycy', 'naśladuje działanie prolaktyny, pobudza laktację od pierwszego trymestru, hamuje wydzielanie progesteronu', 'naśladuje działanie ACTH, pobudza korę nadnerczy, jest stosowana w diagnostyce niewydolności nadnerczy', 'naśladuje działanie oksytocyny, pobudza skurcze macicy, jest stosowana do indukcji porodu'], a: 0, rationale: "Poprawnie: hCG strukturalnie i funkcjonalnie naśladuje LH, pobudzając komórki Leydiga do produkcji testosteronu, dlatego jest wykorzystywana klinicznie w teście stymulacyjnym oceniającym rezerwę czynnościową jąder (zdolność do biosyntezy testosteronu). hCG naśladuje LH, nie FSH, i POBUDZA (nie hamuje) komórki Leydiga — nie jest też stosowana w diagnostyce tarczycy. hCG nie naśladuje prolaktyny — jej główna aktywność biologiczna jest zbliżona do LH, a we wczesnej ciąży wspiera (nie hamuje) wydzielanie progesteronu przez ciałko żółte. hCG nie naśladuje ACTH ani nie jest wykorzystywana w diagnostyce niewydolności nadnerczy — to zupełnie inny obszar zastosowań klinicznych. hCG nie naśladuje oksytocyny i nie jest stosowana do indukcji porodu — to zupełnie odmienne zastosowanie kliniczne, niezwiązane z jej rzeczywistym mechanizmem działania." },
    { oldQ: 'Skutkiem nadczynności przytarczyc jest osteoporoza z preferencyjną utratą jakiego rodzaju kości:', q: 'Skutkiem nadczynności przytarczyc jest osteoporoza z preferencyjną utratą jakiego rodzaju kości?', o: ['kości korowej (zbitej), a nie beleczkowatej', 'kości beleczkowatej (gąbczastej), a nie korowej', 'obu rodzajów kości w jednakowym stopniu', 'wyłącznie chrząstki stawowej, bez wpływu na kość', 'wyłącznie szpiku kostnego, bez wpływu na tkankę kostną'], a: 0, rationale: "Poprawnie: nadmiar parathormonu w nadczynności przytarczyc preferencyjnie nasila resorpcję kości korowej (zbitej), np. w obrębie kości długich, w mniejszym stopniu wpływając na kość beleczkowatą (np. kręgosłup). Twierdzenie o preferencyjnej utracie kości beleczkowatej odwraca rzeczywisty wzorzec utraty masy kostnej typowy dla nadczynności przytarczyc (odmienny np. od osteoporozy pomenopauzalnej, dotyczącej głównie kości beleczkowatej). Wpływ na oba rodzaje kości nie jest jednakowy — istnieje wyraźna preferencja dla kości korowej, co jest istotą tego pytania. Nadczynność przytarczyc wpływa na tkankę KOSTNĄ, nie na chrząstkę stawową, która nie jest głównym celem działania PTH. Nadczynność przytarczyc wpływa przede wszystkim na macierz kostną (resorpcję), nie na szpik kostny jako główny cel działania hormonu." },
    { oldQ: 'Częstym działaniem niepożądanym inhibitorów ACE jest kaszel — jaki jest tego mechanizm:', q: 'Częstym działaniem niepożądanym inhibitorów ACE jest suchy kaszel — jaki jest mechanizm tego zjawiska?', o: ['ACEI hamują rozkład bradykininy, która drażni receptory czuciowe (włókna C) w drogach oddechowych', 'ACEI bezpośrednio uszkadzają nabłonek oskrzeli poprzez działanie toksyczne', 'ACEI nasilają wydzielanie histaminy z mastocytów płuc', 'ACEI powodują skurcz oskrzeli poprzez blokadę receptorów beta-adrenergicznych', 'ACEI zwiększają produkcję angiotensyny II, drażniącej drogi oddechowe'], a: 0, rationale: "Poprawnie: inhibitory ACE hamują enzym konwertujący angiotensynę, który poza aktywacją angiotensyny II odpowiada również za rozkład bradykininy — jej nagromadzenie drażni czuciowe receptory typu C w drogach oddechowych, wywołując charakterystyczny suchy kaszel. ACEI nie działają bezpośrednio toksycznie na nabłonek oskrzeli — mechanizm kaszlu jest pośredni, związany z nagromadzeniem bradykininy, nie bezpośrednim uszkodzeniem tkanki. ACEI nie są klasycznie opisywane jako nasilające wydzielanie histaminy z mastocytów jako główny mechanizm kaszlu polekowego. ACEI nie blokują receptorów beta-adrenergicznych (to mechanizm beta-blokerów) — ich mechanizm działania dotyczy układu renina-angiotensyna-bradykinina. ACEI ZMNIEJSZAJĄ (nie zwiększają) produkcję angiotensyny II poprzez blokadę enzymu konwertującego — to podstawowy, zamierzony mechanizm ich działania przeciwnadciśnieniowego, a kaszel wynika z odrębnego, dodatkowego efektu na bradykininę." },
    { oldQ: 'Prawidłowa wartość frakcji wyrzutowej lewej komory (LVEF):', q: 'Jaka jest prawidłowa wartość frakcji wyrzutowej lewej komory (LVEF)?', o: ['powyżej ok. 55-60%', 'powyżej ok. 90-100%', 'poniżej ok. 30%', 'ok. 10-20%', 'dokładnie 50%, nie mniej i nie więcej'], a: 0, rationale: "Poprawnie: prawidłowa frakcja wyrzutowa lewej komory wynosi zwykle powyżej ok. 55-60%, odzwierciedlając zdolność komory do efektywnego wyrzucania krwi podczas skurczu. Wartości 90-100% są fizjologicznie nierealistyczne dla prawidłowego serca — tak wysoka frakcja wyrzutowa nie występuje w warunkach fizjologicznych. Wartości poniżej 30% wskazują na ciężką dysfunkcję skurczową lewej komory, znacznie poniżej normy, typową dla zaawansowanej niewydolności serca. Wartości 10-20% są skrajnie niskie i wskazywałyby na krytyczną, zagrażającą życiu niewydolność serca, dalekie od normy. Sztywne przyjęcie dokładnie 50% jako jedynej prawidłowej wartości jest nieprecyzyjne — prawidłowy zakres LVEF to przedział wartości powyżej 55-60%, nie pojedyncza liczba." },
    { oldQ: 'Objawy sugerujące hemolizę zewnątrznaczyniową (a nie wewnątrznaczyniową):', q: 'Jakie objawy sugerują hemolizę zewnątrznaczyniową, a nie wewnątrznaczyniową?', o: ['splenomegalia i żółtaczka (z podwyższoną bilirubiną wolną)', 'hemoglobinuria i wyraźny spadek stężenia haptoglobiny', 'hemosyderynuria bez towarzyszącej splenomegalii', 'wyłącznie bezobjawowy przebieg bez odchyleń laboratoryjnych', 'gorączka i dreszcze jako jedyne, dominujące objawy'], a: 0, rationale: "Poprawnie: hemoliza pozanaczyniowa (rozpad erytrocytów w śledzionie/wątrobie przez makrofagi) daje splenomegalię oraz żółtaczkę z podwyższoną bilirubiną wolną (niesprzężoną), będącą produktem trawienia hemoglobiny przez makrofagi. Hemoglobinuria i wyraźny spadek haptoglobiny są typowe dla hemolizy WEWNĄTRZNACZYNIOWEJ, gdzie wolna hemoglobina uwalniana bezpośrednio do krwi wiąże haptoglobinę i przechodzi do moczu. Hemosyderynuria (obecność hemosyderyny w moczu) jest również typowym objawem przewlekłej hemolizy wewnątrznaczyniowej, nie pozanaczyniowej. Hemoliza (niezależnie od typu) daje zwykle wyraźne odchylenia laboratoryjne i kliniczne — bezobjawowy przebieg bez żadnych odchyleń nie jest typowym obrazem hemolizy patologicznej. Gorączka i dreszcze mogą towarzyszyć ostrej hemolizie (zwłaszcza wewnątrznaczyniowej, np. potransfuzyjnej), ale nie są swoistym, głównym objawem różnicującym hemolizę zewnątrznaczyniową." },
    { oldQ: 'Jak nazywa się związek powstający po połączeniu tlenku węgla z hemoglobiną:', q: 'Jak nazywa się związek powstający po połączeniu tlenku węgla (CO) z hemoglobiną?', o: ['karboksyhemoglobina', 'methemoglobina', 'oksyhemoglobina', 'sulfhemoglobina', 'glikohemoglobina'], a: 0, rationale: "Poprawnie: połączenie tlenku węgla z hemoglobiną tworzy karboksyhemoglobinę (COHb), związek o bardzo dużym powinowactwie CO do hemoglobiny, upośledzający transport tlenu i będący podstawą toksyczności zatrucia czadem. Methemoglobina powstaje przy utlenieniu żelaza hemowego z Fe2+ do Fe3+ (np. pod wpływem azotanów/azotynów), niezwiązanym z wiązaniem CO. Oksyhemoglobina to fizjologiczny związek hemoglobiny z TLENEM (O2), odrębny od patologicznego związku z tlenkiem węgla. Sulfhemoglobina powstaje przy nieodwracalnym związaniu siarki z hemoglobiną, rzadkim zjawisku niezwiązanym z ekspozycją na CO. Glikohemoglobina (HbA1c) powstaje przy nieenzymatycznym przyłączeniu glukozy do hemoglobiny, wykorzystywana w monitorowaniu cukrzycy, niezwiązana z tlenkiem węgla." },
    { oldQ: 'Który z procesów oddechowych ma charakter bierny — spokojny wdech czy spokojny wydech:', q: 'Który z procesów oddechowych ma charakter bierny w warunkach spoczynkowych — spokojny wdech czy spokojny wydech?', o: ['spokojny wydech', 'spokojny wdech', 'oba procesy mają charakter aktywny, wymagający skurczu mięśni', 'oba procesy mają charakter całkowicie bierny, bez udziału jakichkolwiek sił', 'zależy wyłącznie od pozycji ciała, niezależnie od fazy oddechu'], a: 0, rationale: "Poprawnie: spokojny wydech w warunkach spoczynkowych jest procesem BIERNYM, wynikającym z elastycznej retrakcji rozciągniętych podczas wdechu płuc i klatki piersiowej, bez potrzeby aktywnego skurczu mięśni wydechowych. Spokojny wdech jest procesem AKTYWNYM, wymagającym skurczu przepony i mięśni międzyżebrowych zewnętrznych — to odwrócenie względem prawidłowej odpowiedzi. Twierdzenie, że oba procesy są aktywne, pomija bierny charakter spokojnego wydechu, kluczową cechę odróżniającą go od wdechu. Twierdzenie, że oba procesy są całkowicie bierne, pomija aktywny, wymagający skurczu mięśni charakter wdechu. Charakter bierny/aktywny tych procesów wynika z mechaniki oddychania (elastyczność płuc, skurcz mięśni), nie z pozycji ciała jako głównego czynnika determinującego." },
    { oldQ: 'Do objawów z kręgu dyspepsji nie należy jaki objaw:', q: 'Który objaw NIE należy do klasycznego kręgu objawów dyspepsji?', o: ['biegunka', 'odbijanie', 'wczesne uczucie sytości', 'zgaga', 'ból w nadbrzuszu'], a: 0, rationale: "Poprawnie: biegunka nie jest klasycznym objawem dyspepsji, która obejmuje głównie dolegliwości górnego odcinka przewodu pokarmowego związane z trawieniem. Odbijanie jest jednym z klasycznych, typowych objawów zaliczanych do zespołu dyspeptycznego. Wczesne uczucie sytości (wczesna sytość poposiłkowa) jest typowym, dobrze udokumentowanym objawem dyspepsji czynnościowej i organicznej. Zgaga (pieczenie zamostkowe) jest klasycznym objawem dyspeptycznym, często związanym z refluksem żołądkowo-przełykowym. Ból w nadbrzuszu jest jednym z głównych, definiujących objawów zespołu dyspeptycznego." },
    { oldQ: 'Dlaczego u zdrowego człowieka dynamiczny wysiłek fizyczny powoduje spadek ESV i wzrost SV w obu komorach:', q: 'Dlaczego u zdrowego człowieka dynamiczny wysiłek fizyczny powoduje spadek objętości końcowoskurczowej (ESV) i wzrost objętości wyrzutowej (SV) w obu komorach?', o: ['z powodu wzrostu stymulacji współczulnej, nasilającej kurczliwość i skuteczniejsze opróżnianie komory', 'z powodu spadku stymulacji współczulnej i przewagi układu przywspółczulnego', 'z powodu zmniejszenia częstości akcji serca podczas wysiłku', 'z powodu zmniejszenia obciążenia następczego do zera podczas wysiłku', 'z powodu całkowitego zahamowania kurczliwości mięśnia sercowego'], a: 0, rationale: "Poprawnie: wysiłek dynamiczny nasila stymulację współczulną, zwiększając kurczliwość mięśnia sercowego (efekt inotropowy dodatni), co pozwala komorze opróżnić się skuteczniej (niższa ESV) i zwiększa objętość wyrzutową (SV). Spadek stymulacji współczulnej i przewaga przywspółczulna byłyby sprzeczne z fizjologiczną reakcją na wysiłek, która wymaga właśnie nasilenia aktywności współczulnej. Wysiłek dynamiczny zwiększa, a nie zmniejsza częstość akcji serca — to podstawowa, dobrze znana reakcja układu krążenia na obciążenie wysiłkiem. Obciążenie następcze podczas wysiłku nie spada do zera — pozostaje istotnym czynnikiem obciążającym serce, choć opór obwodowy w mięśniach pracujących maleje. Kurczliwość mięśnia sercowego podczas wysiłku ROŚNIE (nie jest hamowana) pod wpływem pobudzenia współczulnego, co jest kluczowym mechanizmem zwiększenia SV." },
    { oldQ: 'Spadek objętości krwi krążącej powoduje wzrost wydzielania reniny, aldosteronu i angiotensyny II oraz wzrost resorpcji Na+ — który z tych parametrów jednak spada:', q: 'Spadek objętości krwi krążącej powoduje wzrost wydzielania reniny, aldosteronu i angiotensyny II oraz wzrost resorpcji Na+. Który z parametrów związanych z czynnością nerek mimo to spada?', o: ['ciśnienie perfuzyjne nerek', 'stężenie potasu we krwi', 'wydzielanie wazopresyny', 'częstość akcji serca', 'opór naczyniowy nerek'], a: 0, rationale: "Poprawnie: mimo aktywacji układu RAA (reniny, angiotensyny II, aldosteronu) próbującego skompensować hipowolemię, ciśnienie perfuzyjne nerek pozostaje obniżone (to właśnie ten spadek jest pierwotnym bodźcem aktywującym cały układ RAA). Stężenie potasu we krwi raczej ROŚNIE lub pozostaje względnie stabilne w tym kontekście — aldosteron zwiększa wydalanie potasu, ale nie jest to parametr opisywany jako spadający w odpowiedzi na hipowolemię w tym mechanizmie. Wydzielanie wazopresyny WZRASTA (nie spada) w odpowiedzi na hipowolemię, wspomagając zatrzymywanie wody, równolegle z aktywacją RAA. Częstość akcji serca WZRASTA (tachykardia kompensacyjna) w odpowiedzi na hipowolemię, nie spada. Opór naczyniowy nerek (i całego krążenia) WZRASTA pod wpływem angiotensyny II i katecholamin, próbując utrzymać ciśnienie perfuzyjne — nie jest to parametr spadający." },
    { oldQ: 'Wskaż mediatory zapalenia, które hamują aktywację płytek krwi:', q: 'Wskaż mediatory zapalenia/śródbłonkowe, które hamują aktywację płytek krwi.', o: ['NO i prostacyklina (PGI2)', 'tromboksan A2 i endotelina-1', 'trombina i kolagen', 'ADP i serotonina', 'czynnik von Willebranda i fibrynogen'], a: 0, rationale: "Poprawnie: NO i prostacyklina, wydzielane przez prawidłowy śródbłonek, hamują aktywację i agregację płytek krwi, chroniąc przed nieprawidłowym tworzeniem zakrzepów w nieuszkodzonych naczyniach. Tromboksan A2 i endotelina-1 działają PRZECIWNIE — tromboksan nasila agregację płytek, a endotelina obkurcza naczynia, nie hamując aktywacji płytek. Trombina i kolagen aktywują, a nie hamują płytki krwi — są kluczowymi induktorami ich adhezji i agregacji w procesie krzepnięcia. ADP i serotonina, uwalniane z aktywowanych płytek, nasilają dalszą agregację (dodatnie sprzężenie zwrotne), nie hamują jej. Czynnik von Willebranda i fibrynogen są białkami pośredniczącymi w adhezji i agregacji płytek, wspomagającymi, a nie hamującymi ich aktywację." },
    { oldQ: 'Główna przyczyna powstawania wysięku:', q: 'Jaka jest główna przyczyna powstawania wysięku zapalnego (w odróżnieniu od przesięku)?', o: ['ucieczka białka z osocza do przestrzeni pozanaczyniowej wskutek zwiększonej przepuszczalności śródbłonka', 'wzrost ciśnienia hydrostatycznego w naczyniach włosowatych', 'spadek ciśnienia onkotycznego osocza spowodowany hipoalbuminemią', 'zablokowanie odpływu chłonki z tkanek', 'spadek ciśnienia hydrostatycznego w naczyniach żylnych'], a: 0, rationale: "Poprawnie: wysięk zapalny powstaje głównie wskutek zwiększonej przepuszczalności śródbłonka naczyń (pod wpływem mediatorów zapalnych), umożliwiającej ucieczkę białek osocza do przestrzeni pozanaczyniowej, co odróżnia go od ubogobiałkowego przesięku. Wzrost ciśnienia hydrostatycznego jest głównym mechanizmem powstawania PRZESIĘKU (np. w niewydolności serca), nie wysięku zapalnego. Spadek ciśnienia onkotycznego z powodu hipoalbuminemii jest również mechanizmem przesięku, niezwiązanym bezpośrednio z procesem zapalnym generującym wysięk. Zablokowanie odpływu chłonki powoduje obrzęk limfatyczny, odrębny mechanizm niezwiązany bezpośrednio z definicją wysięku zapalnego. Spadek ciśnienia hydrostatycznego w żyłach nie jest mechanizmem powstawania płynu w przestrzeni pozanaczyniowej — przeciwnie, to raczej wzrost ciśnienia hydrostatycznego sprzyja gromadzeniu się płynu." },
    { oldQ: 'Które włókna nerwowe przewodzą impulsy najszybciej:', q: 'Które włókna nerwowe przewodzą impulsy nerwowe najszybciej?', o: ['włókna grupy A podgrupy α (Aα)', 'włókna grupy C (bezmielinowe)', 'włókna grupy B (przedzwojowe autonomiczne)', 'włókna grupy A podgrupy δ (Aδ)', 'wszystkie rodzaje włókien przewodzą impulsy z jednakową szybkością'], a: 0, rationale: "Poprawnie: włókna Aα, grube i silnie zmielinizowane (odpowiedzialne m.in. za propriocepcję i unerwienie ruchowe mięśni szkieletowych), przewodzą impulsy najszybciej spośród wszystkich typów włókien nerwowych. Włókna grupy C, jako cienkie i bezmielinowe (przewodzące m.in. wolny, tępy ból), przewodzą impulsy najwolniej ze wszystkich typów włókien — to niemal przeciwieństwo najszybszych włókien. Włókna grupy B, cienkie, słabo zmielinizowane włókna przedzwojowe autonomiczne, przewodzą znacznie wolniej niż grube włókna Aα. Włókna Aδ, cieńsze i słabiej zmielinizowane niż Aα (odpowiedzialne za szybki, ostry ból), przewodzą wolniej niż włókna Aα. Szybkość przewodzenia wyraźnie różni się między typami włókien w zależności od ich grubości i stopnia mielinizacji, więc stwierdzenie o jednakowej szybkości jest nieprawdziwe." },
    { oldQ: 'Które zaburzenie mieszane RKZ nie jest możliwe (poza jednoczesną kwasicą i zasadowicą oddechową):', q: 'Które zaburzenie mieszane równowagi kwasowo-zasadowej (RKZ) nie jest fizjologicznie możliwe?', o: ['jednoczesna kwasica i zasadowica oddechowa', 'jednoczesna kwasica metaboliczna i kwasica oddechowa', 'jednoczesna zasadowica metaboliczna i zasadowica oddechowa', 'jednoczesna kwasica metaboliczna i zasadowica metaboliczna o różnym podłożu', 'jednoczesna zasadowica oddechowa i kwasica metaboliczna'], a: 0, rationale: "Poprawnie: kwasica i zasadowica oddechowa nie mogą wystąpić jednocześnie, ponieważ organizm w danym momencie nie może jednocześnie hipowentylować (retencja CO2) i hiperwentylować (utrata CO2) — kierunek zmiany wentylacji pęcherzykowej jest zawsze jeden. Kwasica metaboliczna i kwasica oddechowa mogą współistnieć (np. w zatrzymaniu krążenia), będąc niezależnymi mechanizmami mogącymi się nakładać i potęgować kwasicę. Zasadowica metaboliczna i oddechowa mogą również współistnieć (np. hiperwentylacja przy wymiotach), będąc niezależnymi od siebie procesami. Kwasica i zasadowica metaboliczna o różnym podłożu mogą teoretycznie współistnieć (np. wymioty z jednoczesną kwasicą mleczanową), maskując się częściowo nawzajem. Zasadowica oddechowa i kwasica metaboliczna mogą współistnieć jako niezależne zaburzenia z różnych osi (np. w sepsie z hiperwentylacją i kwasicą mleczanową)." },
    { oldQ: 'Ile wynosi masa szpiku kostnego u dorosłego w przybliżeniu jako procent masy ciała:', q: 'Ile wynosi w przybliżeniu masa szpiku kostnego u dorosłego człowieka jako procent masy ciała?', o: ['ok. 5% masy ciała (ok. 2,5 kg)', 'ok. 20% masy ciała', 'ok. 0,5% masy ciała', 'ok. 50% masy ciała', 'ok. 1% masy ciała'], a: 0, rationale: "Poprawnie: szpik kostny u dorosłego stanowi w przybliżeniu ok. 5% masy ciała (ok. 2,5 kg), będąc istotnym, aktywnym metabolicznie narządem krwiotwórczym. Wartość 20% znacznie zawyża rzeczywisty udział masy szpiku w całkowitej masie ciała. Wartość 0,5% jest zbyt niska w stosunku do rzeczywistej, znaczącej masy szpiku kostnego u dorosłego człowieka. Wartość 50% jest rażąco zawyżona i fizjologicznie niemożliwa dla masy szpiku kostnego. Wartość 1% nieco zaniża rzeczywistą, udokumentowaną proporcję masy szpiku kostnego względem całkowitej masy ciała." },
    { oldQ: 'Jakie pH panuje w dwunastnicy:', q: 'Jakie pH panuje fizjologicznie w świetle dwunastnicy?', o: ['lekko zasadowe (ok. 7,1-8,2), dzięki neutralizacji przez wodorowęglany trzustkowe', 'silnie kwaśne (ok. 1-2), podobnie jak w żołądku', 'obojętne, dokładnie 7,0, bez wahań', 'silnie zasadowe (ok. 10-12)', 'umiarkowanie kwaśne (ok. 4-5)'], a: 0, rationale: "Poprawnie: treść żołądkowa napływająca do dwunastnicy jest neutralizowana przez wodorowęglany wydzielane przez trzustkę, ustalając lekko zasadowe środowisko (ok. 7,1-8,2), optymalne dla działania enzymów trzustkowych. Silnie kwaśne pH (1-2) jest typowe dla ŻOŁĄDKA, nie dwunastniny — po opuszczeniu żołądka treść jest neutralizowana. Dokładnie obojętne pH 7,0 bez wahań nie oddaje rzeczywistego, nieco zasadowego charakteru środowiska dwunastniczego. Silnie zasadowe pH (10-12) znacznie przekracza rzeczywisty, umiarkowanie zasadowy zakres panujący w dwunastnicy. Umiarkowanie kwaśne pH (4-5) nie oddaje właściwej, zasadowej natury środowiska dwunastniczego po neutralizacji przez wodorowęglany trzustkowe." },
    { oldQ: 'Czym różni się surowica od osocza:', q: 'Czym różni się surowica od osocza krwi?', o: ['surowica nie zawiera czynników krzepnięcia, które zostały zużyte podczas procesu krzepnięcia', 'surowica zawiera więcej czynników krzepnięcia niż osocze', 'osocze nie zawiera fibrynogenu, w przeciwieństwie do surowicy', 'surowica i osocze są dokładnie tym samym, różniącym się jedynie nazwą', 'surowica zawiera elementy morfotyczne krwi, a osocze ich nie zawiera'], a: 0, rationale: "Poprawnie: surowica to osocze pozbawione czynników krzepnięcia (w tym fibrynogenu), które zostały zużyte w procesie krzepnięcia krwi podczas tworzenia skrzepu przed odwirowaniem. Twierdzenie, że surowica zawiera więcej czynników krzepnięcia, jest odwróceniem rzeczywistej relacji — to właśnie ich brak definiuje surowicę. To OSOCZE zawiera fibrynogen (jeden z czynników krzepnięcia), a surowica go NIE zawiera — to odwrócenie prawidłowego przypisania. Surowica i osocze różnią się istotnie zawartością czynników krzepnięcia, co jest kluczową, praktyczną różnicą wykorzystywaną w laboratorium — nie są tym samym. Ani surowica, ani osocze nie zawierają elementów morfotycznych krwi (komórek) — obie są płynną frakcją krwi po usunięciu komórek (przez wirowanie), różniącą się jedynie obecnością/brakiem czynników krzepnięcia." },
    { oldQ: 'Dlaczego ściana prawej komory jest cieńsza niż ściana lewej komory:', q: 'Dlaczego ściana prawej komory serca jest cieńsza niż ściana lewej komory?', o: ['ponieważ prawa komora pompuje krew do krążenia płucnego o mniejszym oporze naczyniowym', 'ponieważ prawa komora przyjmuje mniejszą objętość krwi niż lewa komora', 'ponieważ prawa komora pracuje z mniejszą częstością niż lewa komora', 'ponieważ prawa komora generuje wyższe ciśnienie niż lewa komora, wymagając mniej mięśnia', 'ponieważ prawa komora jest unerwiona wyłącznie przywspółczulnie'], a: 0, rationale: "Poprawnie: prawa komora tłoczy krew do krążenia płucnego o niskim oporze naczyniowym, więc wymaga wygenerowania znacznie niższego ciśnienia niż lewa komora pompująca do krążenia systemowego — stąd cieńsza ściana mięśniowa. Obie komory w warunkach fizjologicznych przyjmują tę samą objętość krwi (rzuty minutowe są sobie równe), więc różnica objętości nie tłumaczy różnicy grubości ścian. Obie komory pracują z tą samą częstością (biją synchronicznie w ramach jednego cyklu serca), więc częstość nie jest przyczyną różnicy grubości. Prawa komora generuje NIŻSZE, a nie wyższe ciśnienie niż lewa — to odwrócenie rzeczywistej zależności ciśnieniowej leżącej u podstaw różnicy grubości ścian. Obie komory są unerwione zarówno współczulnie, jak i przywspółczulnie — nie ma różnicy w rodzaju unerwienia tłumaczącej grubość ściany." },
  ]
};
const raw = JSON.parse(fs.readFileSync('fizjopato_raw.json', 'utf8'));
let totalConverted = 0;
const out = raw.map(item => {
  const list = categories[item.category];
  if (!list) return item;
  const c = list.find(x => x.oldQ === item.q);
  if (!c) {
    if (item.mode === 'typed') console.log('TYPED MISS [' + item.category + ']:', item.q);
    return item;
  }
  totalConverted++;
  return { category: item.category, q: c.q, o: c.o, a: c.a, rationale: c.rationale };
});
for (const cat of Object.keys(categories)) {
  const remaining = out.filter(i => i.category === cat && i.mode === 'typed').length;
  console.log(cat, '-> remaining typed:', remaining);
}
console.log('total converted:', totalConverted);
fs.writeFileSync('fizjopato_raw.json', JSON.stringify(out, null, 2));
